export const getGenerateContentUrl = () => {




  return `/api/generate`
}

/**
 * @summary Generate a content draft using AI
 */
export const generateContent = async (generateContentInput: GenerateContentInput, options?: Parameters<typeof customFetch>[1]): Promise<GeneratedContent> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<GeneratedContent>(getGenerateContentUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(generateContentInput)
  }
);}





export const getGenerateContentMutationKey = () => ['generateContent'] as const;

export const getGenerateContentMutationOptions = <TError = ErrorType<BadRequestResponse | UnauthorizedResponse | NotFoundResponse | Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateContent>>, TError,GenerateContentMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof generateContent>>, TError,GenerateContentMutationVariables, TContext> => {

const mutationKey = getGenerateContentMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof generateContent>>, GenerateContentMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  generateContent(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type GenerateContentMutationResult = NonNullable<Awaited<ReturnType<typeof generateContent>>>
    export type GenerateContentMutationBody = BodyType<GenerateContentInput>
    export type GenerateContentMutationError = ErrorType<BadRequestResponse | UnauthorizedResponse | NotFoundResponse | Error>
    export type GenerateContentMutationVariables = {data: BodyType<GenerateContentInput>}

    /**
 * @summary Generate a content draft using AI
 */
export const useGenerateContent = <TError = ErrorType<BadRequestResponse | UnauthorizedResponse | NotFoundResponse | Error>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof generateContent>>, TError,GenerateContentMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof generateContent>>,
        TError,
        GenerateContentMutationVariables,
        TContext
      > => {
      return useMutation(getGenerateContentMutationOptions(options), queryClient);
    }

